// frontend/src/CalculatorForm.js
import React, { useState } from 'react';

function CalculatorForm({ onCalculate }) {
  const [hashrate, setHashrate] = useState('');
  const [powerConsumption, setPowerConsumption] = useState('');
  const [electricityCost, setElectricityCost] = useState('');
  const [bitcoinPrice, setBitcoinPrice] = useState('');
  const [networkDifficulty, setNetworkDifficulty] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onCalculate({
      hashrate: Number(hashrate),
      powerConsumption: Number(powerConsumption),
      electricityCost: Number(electricityCost),
      bitcoinPrice: Number(bitcoinPrice),
      networkDifficulty: Number(networkDifficulty)
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Hashrate:
          <input type="number" value={hashrate} onChange={(e) => setHashrate(e.target.value)} required />
        </label>
      </div>
      <div>
        <label>Power Consumption (watts):
          <input type="number" value={powerConsumption} onChange={(e) => setPowerConsumption(e.target.value)} required />
        </label>
      </div>
      <div>
        <label>Electricity Cost ($/kWh):
          <input type="number" value={electricityCost} onChange={(e) => setElectricityCost(e.target.value)} required />
        </label>
      </div>
      <div>
        <label>Bitcoin Price:
          <input type="number" value={bitcoinPrice} onChange={(e) => setBitcoinPrice(e.target.value)} required />
        </label>
      </div>
      <div>
        <label>Network Difficulty:
          <input type="number" value={networkDifficulty} onChange={(e) => setNetworkDifficulty(e.target.value)} required />
        </label>
      </div>
      <button type="submit">Calculate</button>
    </form>
  );
}

export default CalculatorForm;
